import re
import json

# Function to extract table data from text
def extract_table(text):
    """Extract fiscal year data from markdown table"""
    lines = text.strip().split('\n')
    result = {}
    for line in lines:
        # Match patterns like | 2010 | 2161728 | 3455931 |
        match = re.search(r'\|\s*(\d{4})\s*\|[\s\d,]*\|[\s\d,]*\|[\s\d,]*\|', line)
        if match:
            year = match.group(1)
            if year.isdigit() and 2010 <= int(year) <= 2024:
                # Extract all numbers from the line
                numbers = re.findall(r'[\d,]+', line)
                if len(numbers) >= 4:
                    receipts = int(numbers[1].replace(',', ''))
                    outlays = int(numbers[3].replace(',', ''))
                    result[int(year)] = {'receipts': receipts, 'outlays': outlays}
    return result

